document.addEventListener("DOMContentLoaded",function(){const sidebar=document.getElementById("sidebar"),toggleBtn=document.getElementById("sidebarToggle"),sidebarNav=document.querySelector(".sidebar-nav");window._toastEl=document.getElementById("toast");window._toastMsgEl=document.getElementById("toastMsg");window._clockEl=document.querySelector(".stat-value.clock-value");if(toggleBtn&&sidebar){toggleBtn.setAttribute("aria-expanded","false");toggleBtn.addEventListener("click",function(){const isOpen=sidebar.classList.toggle("open");toggleBtn.setAttribute("aria-expanded",isOpen?"true":"false");});}if(sidebarNav){sidebarNav.addEventListener("click",function(e){const item=e.target.closest(".nav-item");if(!item) return;e.preventDefault();const active=sidebarNav.querySelector(".nav-item.active");if(active&&active!==item) active.classList.remove("active");item.classList.add("active");});}updateClock();setInterval(updateClock,1e3);});let toastTimer;function showToast(message){const toast=window._toastEl||document.getElementById("toast"),msg=window._toastMsgEl||document.getElementById("toastMsg");if(!toast||!msg)return;msg.textContent=message;toast.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>{toast.classList.remove("show")},2500)}function updateClock(){const clockEl=window._clockEl||document.querySelector(".stat-value.clock-value");if(!clockEl)return;const now=new Date();let hours=now.getHours();const minutes=now.getMinutes().toString().padStart(2,"0"),seconds=now.getSeconds().toString().padStart(2,"0");const ampm=hours>=12?"PM":"AM";hours=hours%12||12;clockEl.textContent=`${hours}:${minutes}:${seconds} ${ampm}`}